BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO question_seed
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Сколько уровней привилегий процессора x86-64 использует Linux?', '{"A":"Два: кольцо 0 для ядра и кольцо 3 для программ","B":"Три: ядро, драйверы и программы","C":"Один: все программы работают с полными правами","D":"Четыре: все кольца от 0 до 3"}'::jsonb, 'A', 'Программы работают в пользовательском режиме, ядро — в режиме ядра. Сколько времени процессор проводит в каждом из них, показывают столбцы us и sy: vmstat 1 5.', '{"A":"Остальные кольца процессора Linux не использует.","B":"Отдельного кольца для драйверов Linux не выделяет: драйверы ядра работают в кольце 0, а пользовательские части драйверов — в кольце 3.","C":"Тогда любая программа могла бы обратиться к устройствам и чужой памяти.","D":"Колец у процессора четыре, но Linux использует только два из них."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что обычной программе в пользовательском режиме запрещено делать напрямую?', '{"A":"Останавливать процессор инструкцией hlt","B":"Отключать прерывания","C":"Выполнять арифметику и условные переходы","D":"Читать и записывать свою собственную память","E":"Менять таблицы страниц, то есть перевод своих виртуальных адресов в физические"}'::jsonb, 'ABE', 'Всё, что затрагивает устройства, чужую память и управление процессором, программа просит у ядра через системные вызовы. Опыт 5 в examples/syscalls.c показывает попытку выполнить hlt (только на учебной машине); что значат сигналы: man 7 signal.', '{"A":"Это привилегированная инструкция, она разрешена только ядру.","B":"Иначе программа могла бы занять процессор навсегда.","C":"Обычные инструкции программа выполняет без обращения к ядру.","D":"К разрешённым страницам своей памяти программа обращается напрямую; ядро вмешивается при страничных ошибках — например, когда страницы ещё нет или при копировании при записи.","E":"Иначе программа могла бы добраться до чужой памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что произойдёт при запуске этой программы обычным пользователем на Linux x86-64?
```
int main(void)
{
    __asm__ volatile("hlt");
    return 0;
}
```', '{"A":"Программа не скомпилируется","B":"Инструкция будет пропущена, и программа вернёт 0","C":"Процессор остановится до следующего прерывания","D":"Процессор не выполнит инструкцию, ядро завершит процесс сигналом SIGSEGV"}'::jsonb, 'D', 'В терминале это выглядит как Segmentation fault. Код завершения после сигнала: echo $? покажет 139, то есть 128 + 11 (номер SIGSEGV).', '{"A":"Компилятор вставит инструкцию: запрет проверяет процессор во время выполнения.","B":"Процессор не пропускает запрещённую инструкцию, а сообщает об ошибке.","C":"Так hlt работает только в режиме ядра.","D":"Привилегированная инструкция в кольце 3 вызывает ошибку защиты, её обрабатывает ядро."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Как процессор переходит из пользовательского режима в режим ядра?', '{"A":"Программа вызывает нужную функцию ядра по её адресу","B":"Устройство или таймер присылает прерывание","C":"Программа записывает 0 в служебный регистр уровня привилегий","D":"Выполняемая инструкция вызывает исключение, например страничную ошибку","E":"Программа выполняет системный вызов"}'::jsonb, 'BDE', 'Все три пути ведут в заранее приготовленные ядром места. Счётчики прерываний по ядрам процессора: grep LOC /proc/interrupts (повторите через пару секунд и сравните).', '{"A":"Код ядра недоступен из пользовательского режима; переход возможен только по заранее заданным ядром адресам.","B":"Прерывание приходит независимо от того, чем занята программа.","C":"Повысить свой уровень программа не может: это и есть смысл защиты.","D":"Ядро обрабатывает исключение и обычно возвращает управление на ту же инструкцию.","E":"Это предусмотренный ОС способ попросить её об услуге: записать файл, получить память, создать процесс."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Зачем ядру нужно регулярное прерывание от таймера?', '{"A":"Чтобы получать от диска сообщения об окончании чтения","B":"Чтобы регулярно получать управление и отдавать процессор другим задачам, даже если программа не делает системных вызовов","C":"Чтобы проверять права доступа к файлам","D":"Чтобы синхронизировать системные часы по сети"}'::jsonb, 'B', 'Переключения процесса бывают добровольные (он сам ждёт) и вынужденные (его вытеснил планировщик). Счётчики своей оболочки: grep ctxt /proc/$$/status.', '{"A":"Об окончании чтения сообщает прерывание от самого устройства.","B":"Так работает вытесняющая многозадачность: зависшая программа не захватит процессор навсегда.","C":"Права проверяются при системных вызовах, например при открытии файла.","D":"Это делает отдельная служба точного времени, а не прерывание таймера."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Программа получила новую анонимную область памяти через mmap и впервые записывает в одну из её страниц. Что верно?', '{"A":"Ядро выделяет физическую страницу и повторяет инструкцию, программа этого не замечает","B":"Возникает страничная ошибка — исключение процессора","C":"Ядро читает страницу из свопа","D":"Программа снова обращается к ядру вызовом mmap","E":"Процесс получает сигнал SIGSEGV"}'::jsonb, 'AB', 'С новой областью mmap так бывает всегда; malloc же может вернуть уже использованную память, а glibc сама пишет служебные данные в начало блока. Мелкие страничные ошибки обходятся без диска, крупные требуют чтения из файла или свопа. Счётчики процесса: ps -o pid,min_flt,maj_flt,cmd -p PID. Опыт 4 в examples/syscalls.c считает их при записи в 64 МБ.', '{"A":"Так работает выделение памяти по требованию.","B":"Страница пока есть только в виде адресов, в таблице страниц её нет.","C":"Новая страница ещё нигде не хранилась: это мелкая ошибка, без обращения к диску.","D":"Адреса уже получены; страницу выдаёт обработчик исключения, а не новый системный вызов.","E":"Адрес принадлежит процессу и доступ разрешён, поэтому ядро просто выдаёт страницу."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что такое системный вызов?', '{"A":"Сигнал, который ядро посылает программе","B":"Обращение программы к ядру с просьбой выполнить действие, которое ей запрещено в пользовательском режиме","C":"Команда оболочки, например ls или cat","D":"Вызов любой функции из стандартной библиотеки C"}'::jsonb, 'B', 'В Linux около 350 системных вызовов. Список с описаниями: man 2 syscalls; описание одного вызова: man 2 write.', '{"A":"Сигнал направлен от ядра к программе, а системный вызов — наоборот.","B":"Например, записать файл, получить память или создать процесс.","C":"Это программы; они сами пользуются системными вызовами.","D":"Многие функции libc работают целиком в программе и ядро не вызывают."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что верно для функции write() в программе на C?', '{"A":"printf вызывает её при каждом обращении","B":"Ошибку ядра она возвращает как -1, а код ошибки кладёт в errno","C":"Это обёртка из libc: она раскладывает параметры и выполняет инструкцию перехода в ядро","D":"Сама функция write выполняется в режиме ядра"}'::jsonb, 'BC', 'Описание системного вызова — в разделе 2 справки, библиотечной функции — в разделе 3: man 2 write и man 3 printf.', '{"A":"printf копит данные в буфере и вызывает write реже.","B":"Ядро возвращает отрицательный код, обёртка переводит его в привычный для C вид.","C":"Саму запись выполняет ядро.","D":"Обёртка работает в программе; в режим ядра процессор переходит по инструкции syscall."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', '{"A":"strace переименовывает вызовы для краткости","B":"Функции glibc open() и fork() выполняют системные вызовы openat и clone","C":"Ядро отклонило open и fork и подставило другие вызовы","D":"Это вызовы самой strace, а не программы"}'::jsonb, 'B', 'Поэтому при чтении вывода strace ищут openat, а не open. На учебной машине: strace -e trace=openat cat /etc/hostname.', '{"A":"strace показывает вызовы так, как их выполнила программа.","B":"Имена обёрток и вызовов ядра совпадают не всегда.","C":"Ядро ничего не подставляет: так устроены обёртки в glibc.","D":"strace показывает вызовы наблюдаемой программы."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', '{"A":"Передаёт имя вызова строкой","B":"Кладёт номер в переменную errno","C":"Кладёт номер вызова в регистр rax и выполняет инструкцию syscall","D":"Записывает номер в файл /proc/self/syscall"}'::jsonb, 'C', 'Номера зависят от архитектуры процессора. Значение от -4095 до -1 в rax означает ошибку. Таблица номеров: man 2 syscall; на учебной машине номер, в котором ждёт процесс: cat /proc/PID/syscall.', '{"A":"Ядро различает вызовы по номерам: у write номер 1, у read — 0.","B":"В errno обёртка записывает код ошибки после вызова.","C":"Параметры передаются в регистрах rdi, rsi, rdx, r10, r8 и r9, результат возвращается в rax.","D":"Этот файл только показывает, в каком вызове процесс ждёт сейчас."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Допишите вызов, чтобы напечатать строку вызовом ядра по номеру, минуя обёртку write (Linux x86-64):
```
static const char msg[] = "hello\n";
___(SYS_write, 1, msg, sizeof msg - 1);
```', '{"A":"`sys_write`","B":"`write`","C":"`syscall`","D":"`printf`"}'::jsonb, 'C', 'SYS_write из sys/syscall.h равен 1. Длину считает компилятор: sizeof msg - 1, без завершающего нуля. Увидеть вызов на учебной машине: strace -e trace=write ./программа.', '{"A":"Так называется функция внутри ядра; программе она недоступна.","B":"Это обёртка: номер вызова она подставляет сама, а первый параметр у неё — номер файла.","C":"Функция syscall из unistd.h выполняет системный вызов с указанным номером.","D":"printf принимает строку формата, а не номер вызова."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что напечатает этот фрагмент?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', '{"A":"`-9 Bad file descriptor`","B":"`0 Success`","C":"`-1 Bad file descriptor`","D":"`1 Success`"}'::jsonb, 'C', 'Код ошибки сохраняют сразу после неудачного вызова, пока его не изменили другие функции. Названия кодов: man 3 errno. Тот же опыт есть в examples/syscalls.c.', '{"A":"Ядро действительно возвращает -9, но обёртка libc превращает это в -1 и записывает 9 в errno.","B":"Вызов не удался: записывать некуда.","C":"Файла с отрицательным номером не бывает: ядро возвращает ошибку EBADF.","D":"1 вернулось бы, если бы байт был записан."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Когда в программе на C имеет смысл читать errno?', '{"A":"После каждого вызова: значение 0 означает успех","B":"Только после вызовов printf","C":"В любой момент: в errno хранится последняя ошибка всех процессов системы","D":"После того как функция сообщила об ошибке, например вернула -1"}'::jsonb, 'D', 'Если после ошибки будут другие вызовы, код сохраняют сразу: int saved = errno. Список кодов: man 3 errno.', '{"A":"Успешный вызов не обнуляет errno: там может остаться код старой ошибки.","B":"errno заполняют многие функции и системные вызовы.","C":"errno своя у каждого потока каждого процесса.","D":"errno объясняет причину уже случившейся ошибки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что такое файловый дескриптор?', '{"A":"Полный путь к файлу","B":"Номер файла внутри файловой системы (inode)","C":"Номер открытого файла, канала или сокета в таблице процесса; его возвращает open","D":"Номер процесса, который открыл файл"}'::jsonb, 'C', 'Ссылки на открытые файлы процесса лежат в /proc/PID/fd: ls -l /proc/$$/fd.', '{"A":"Путь нужен только при открытии; потом работают с номером.","B":"inode относится к файлу на диске, а дескриптор — к открытому файлу в процессе.","C":"Дальше программа обращается к файлу по этому номеру.","D":"Номер процесса — PID, это другое."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Допишите номер файла, чтобы сообщение ушло в стандартный поток ошибок:
```
static const char msg[] = "ошибка\n";
write(___, msg, sizeof msg - 1);
```', '{"A":"`0`","B":"`3`","C":"`2`","D":"`1`"}'::jsonb, 'C', 'При запуске из оболочки 0, 1 и 2 открыты заранее; оболочка может их перенаправить: 2> errors.log отправит ошибки в файл. Проверка: ls -l /proc/$$/fd.', '{"A":"Номер 0 — стандартный ввод.","B":"Номер 3 обычно получает первый файл, который программа откроет сама.","C":"Номер 2 — стандартный вывод ошибок.","D":"Номер 1 — стандартный вывод; его можно перенаправить отдельно от ошибок."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Вызов write успешно записал все байты в обычный файл на диске; файл открыт без O_SYNC, O_DSYNC и O_DIRECT. Что верно?', '{"A":"Другие процессы уже могут прочитать эти данные из файла","B":"Данные переданы ядру и обычно лежат в кеше страниц","C":"Сохранность данных при сбое питания или ОС не гарантирована","D":"Данные гарантированно ещё не на диске","E":"Данные гарантированно уже записаны на диск"}'::jsonb, 'ABC', 'Разница между записью в кеш и записью со сбросом видна в опыте 3 examples/syscalls.c; его запускают на учебной машине: cc -O0 -Wall -o /tmp/syscalls examples/syscalls.c && /tmp/syscalls.', '{"A":"Чтение идёт через тот же кеш страниц.","B":"На диск ядро запишет их позже, если ещё не успело.","C":"Гарантию даёт успешная синхронизация, например fsync или fdatasync.","D":"Ядро могло успеть записать их в фоне.","E":"Это возможно, но не гарантировано."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Допишите флаг, чтобы каждая запись в файл сама ждала сброса данных на диск, как будто после неё вызван fdatasync:
```
int fd = open("wal.bin", O_WRONLY | O_CREAT | ___, 0600);
```', '{"A":"`O_EXCL`","B":"`O_APPEND`","C":"`O_TRUNC`","D":"`O_DSYNC`"}'::jsonb, 'D', 'Этим флагом пользуется значение open_datasync параметра wal_sync_method в PostgreSQL. Флаг O_SYNC делает то же, но как будто после записи вызван fsync. Описание флагов: man 2 open.', '{"A":"Вместе с O_CREAT этот флаг требует, чтобы файла ещё не было.","B":"Этот флаг заставляет дописывать в конец файла, а не сбрасывать на диск.","C":"Этот флаг обрезает существующий файл до нуля.","D":"С этим флагом write возвращается только после записи данных на устойчивый носитель."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что не так в этом фрагменте?
```
write(fd, buf, len);
if (fdatasync(fd) == 0)
    printf("данные надёжно сохранены\n");
```', '{"A":"После успешного fdatasync данные всё ещё только в кеше ядра","B":"fdatasync нужно вызывать до write","C":"fdatasync нельзя вызывать для обычных файлов","D":"Не проверен результат write: он мог записать меньше len байт или вернуть ошибку, а fdatasync сохранит только записанное"}'::jsonb, 'D', 'Надёжная запись дописывает остаток при неполной записи, повторяет вызов при EINTR и только потом вызывает fdatasync. Пример функции write_durable — в главе 7 материала. Справка: man 2 write, man 2 fsync.', '{"A":"Успешный fdatasync как раз дожидается записи на устойчивый носитель.","B":"Сброс имеет смысл после записи: он сохраняет уже переданные ядру данные.","C":"Наоборот, он предназначен именно для них.","D":"Успех fdatasync не исправляет ошибку предыдущей записи."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Программа напечатала через printf короткую строку без перевода строки; вся строка ещё лежит в буфере stdout и в файл не передана. Затем программа успешно вызвала fork. Вывод перенаправлен в файл, оба процесса завершились через exit. Что окажется в файле?', '{"A":"Строка дважды: буфер скопировался в ребёнка, и его сбросили оба процесса","B":"Строка один раз","C":"Ничего не окажется","D":"Строка появится, только если вызвать fsync"}'::jsonb, 'A', 'Поэтому перед fork вызывают fflush(stdout). А ребёнок, который завершается через _exit, должен сбросить свой вывод сам: _exit буферы не сбрасывает. Правила буферизации: man 3 stdio; что делает exit: man 3 exit.', '{"A":"fork копирует буфер stdio вместе с памятью, и при exit каждый процесс сбрасывает свою копию.","B":"Так было бы, если бы перед fork вызвали fflush(stdout).","C":"exit сбрасывает буферы stdio, поэтому строка будет записана.","D":"fsync отвечает за сброс на диск, а не за сброс буфера printf."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что верно для системных вызовов fork и execve?', '{"A":"fork создаёт копию процесса: родителю возвращает номер ребёнка, ребёнку — 0","B":"execve создаёт новый процесс","C":"execve заменяет программу в текущем процессе, номер процесса сохраняется","D":"fork сразу копирует всю память родителя","E":"PostgreSQL в Linux запускает каждый обслуживающий процесс через fork и затем execve"}'::jsonb, 'AC', 'Так оболочка запускает команды: fork, затем execve в ребёнке и wait в родителе. На учебной машине: strace -f -e trace=%process sh -c ''ls / > /dev/null; :''.', '{"A":"По результату fork процесс понимает, кто он.","B":"Новый процесс создаёт fork; execve только меняет программу.","C":"Прежние код и данные исчезают; открытые файлы остаются, кроме помеченных FD_CLOEXEC.","D":"Страницы остаются общими, пока в них не запишут: копирование при записи.","E":"В Linux postmaster вызывает только fork: копия сразу работает как обслуживающий процесс."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что напечатает родитель, если fork и waitpid выполнились успешно?
```
pid_t child = fork();
if (child == 0)
    _exit(3);
int status;
waitpid(child, &status, 0);
if (WIFEXITED(status))
    printf("%d\n", WEXITSTATUS(status));
```', '{"A":"`0`","B":"Ничего: _exit завершит оба процесса","C":"Номер процесса ребёнка","D":"`3`"}'::jsonb, 'D', 'WEXITSTATUS имеет смысл только после проверки WIFEXITED: процесс мог погибнуть от сигнала. В оболочке код завершения последней команды показывает echo $?.', '{"A":"0 fork вернул ребёнку; код завершения у ребёнка — 3.","B":"_exit завершает только вызвавший его процесс — ребёнка.","C":"WEXITSTATUS даёт код завершения, а не номер процесса.","D":"Ребёнок завершился с кодом 3, родитель получил его через waitpid."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что значит состояние Z у процесса в выводе ps?', '{"A":"Процесс выполняется в режиме ядра","B":"Процесс ждёт ввода-вывода и не прерывается","C":"Процесс завершился, но родитель ещё не забрал его код завершения вызовом wait","D":"Процесс остановлен сигналом SIGSTOP"}'::jsonb, 'C', 'postmaster получает сигнал SIGCHLD и забирает завершившихся детей вызовом waitpid, поэтому зомби среди процессов PostgreSQL обычно не задерживаются. Проверка: ps -o pid,ppid,stat,comm -u postgres.', '{"A":"Выполняющийся процесс — в состоянии R, независимо от режима.","B":"Это состояние D.","C":"Такой процесс называют зомби: память освобождена, осталась только запись о нём.","D":"Это состояние T."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Через какие системные вызовы malloc получает память у ядра в Linux?', '{"A":"`shmget`","B":"`fork`","C":"`mmap` — создаёт новую область адресов","D":"`read`","E":"`brk` — сдвигает границу кучи"}'::jsonb, 'CE', 'Небольшие освобождённые блоки malloc оставляет себе для повторного использования, поэтому после free процесс не обязательно уменьшается. На учебной машине: strace -e trace=brk,mmap ls /.', '{"A":"Это сегмент общей памяти System V, malloc им не пользуется.","B":"fork создаёт процесс, память им не выделяют.","C":"Так glibc выделяет крупные блоки: начальный порог — 128 КБ, но во время работы glibc его повышает, а запрос может быть выполнен и из уже полученной памяти.","D":"read читает данные из файла в уже выделенную память.","E":"Так обычно получают место для небольших блоков."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Какие сигналы посылаются при управлении PostgreSQL?', '{"A":"pg_ctl stop -m fast — SIGINT главному процессу","B":"SELECT pg_reload_conf(); — SIGHUP главному процессу","C":"pg_ctl stop -m immediate — SIGTERM главному процессу","D":"pg_cancel_backend(pid) — SIGKILL обслуживающему процессу","E":"pg_terminate_backend(pid) — SIGTERM обслуживающему процессу"}'::jsonb, 'ABE', 'Сигналы — короткие уведомления процессу, их отправляет системный вызов kill. В журнале сервера бывают сообщения о перечитывании конфигурации, остановке и отмене запроса, но это не полный список отправленных сигналов. Имена и номера сигналов показывает kill -l.', '{"A":"Быстрая остановка: клиенты отключаются, затем выполняется контрольная точка.","B":"Получив SIGHUP, сервер перечитывает конфигурацию.","C":"immediate посылает SIGQUIT; SIGTERM соответствует режиму smart.","D":"Отмене запроса соответствует SIGINT; SIGKILL PostgreSQL для этого не использует.","E":"Процесс завершает сеанс."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Как postmaster обслуживает новое подключение клиента в Linux?', '{"A":"Передаёт соединение одному из заранее запущенных процессов","B":"Создаёт новый поток внутри своего процесса","C":"Запускает новую программу postgres вызовом execve","D":"Принимает его вызовом accept и создаёт обслуживающий процесс вызовом fork; ребёнок наследует дескриптор соединения"}'::jsonb, 'D', 'Поэтому частые короткие подключения дороги: каждое — это accept и fork. Какие порты слушает сервер: ss -ltn; Unix-сокет в Debian: ls -l /var/run/postgresql/.', '{"A":"Без внешнего пула соединений обслуживающий процесс создаётся для каждого подключения.","B":"PostgreSQL использует процессы, а не потоки.","C":"В Linux postmaster вызывает только fork, без execve.","D":"Дальше с клиентом общается только ребёнок, а postmaster снова ждёт подключений."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что показывает столбец sy в выводе top и vmstat?', '{"A":"Долю процессорного времени в режиме ядра","B":"Число системных вызовов в секунду","C":"Долю времени системных служб systemd","D":"Время ожидания ввода-вывода"}'::jsonb, 'A', 'us — время в программах, sy — в ядре; время обработки прерываний top показывает отдельно, в столбцах hi и si. Первую строку vmstat пропускают: vmstat 1 5.', '{"A":"Высокое значение — повод выяснить, какую работу ядро выполняет за программы.","B":"Это доля времени, а не число вызовов: высокий sy может дать и небольшое число дорогих операций.","C":"Службы работают как обычные программы и учитываются в us и sy.","D":"Это столбец wa."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', '{"A":"Большую часть процессорного времени программа провела в режиме ядра, выполняющем для неё работу","B":"sys — время работы других программ системы","C":"Программа 1.6 секунды ждала диска","D":"Программа работала в 1.6 потоках"}'::jsonb, 'A', 'Сравните на любой машине: time dd if=/dev/zero of=/dev/null bs=1 count=1000000 и time dd if=/dev/zero of=/dev/null bs=1000000 count=1. Объём одинаковый, а sys различается на порядки.', '{"A":"Обычно это признак множества системных вызовов или дорогих операций ядра.","B":"sys — время ядра на измеряемую команду и её дочерние процессы, а не на посторонние программы.","C":"Ожидание не расходует процессорное время и в sys не входит.","D":"sys — время, а не число потоков."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Что верно для утилиты strace?', '{"A":"Показывает только номера вызовов, без данных","B":"Безопасна для подключения к рабочему серверу PostgreSQL в часы нагрузки","C":"Может вывести содержимое данных программы, в том числе пароли и тексты запросов","D":"Показывает системные вызовы программы с параметрами и результатами","E":"Может существенно замедлить наблюдаемый процесс, особенно при частых системных вызовах"}'::jsonb, 'CDE', 'На рабочем сервере смотрят /proc и обычные команды, а strace запускают на учебной машине: strace -e trace=write echo hello.', '{"A":"strace печатает и строки, которые программа читает и пишет.","B":"Замедление и раскрытие данных делают её инструментом учебной машины.","C":"Поэтому необработанный вывод чужих программ не публикуют.","D":"Например, write(1, \"hello\\n\", 6) = 6.","E":"Каждый отслеживаемый вызов останавливает процесс, чтобы strace его записала; насколько это заметно, зависит от нагрузки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'Допишите ключ strace, чтобы получить сводку: сколько раз вызывался каждый системный вызов и сколько времени занял:
```
strace ___ ls / > /dev/null
```', '{"A":"`-e`","B":"`-p`","C":"`-f`","D":"`-c`"}'::jsonb, 'D', 'Сводка покажет, сколько вызовов нужно даже простой команде: openat, mmap, read, close и другие. Команда на учебной машине: strace -c ls / > /dev/null.', '{"A":"Задаёт фильтр, какие вызовы показывать.","B":"Подключается к уже работающему процессу по номеру.","C":"Следит ещё и за дочерними процессами.","D":"Выводит таблицу с числом вызовов и временем по каждому."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '19.'), 'В /proc/PID/syscall обслуживающего процесса PostgreSQL первое поле равно 232. Что это значит?', '{"A":"232 — номер текущего запроса клиента","B":"Процесс выполнил 232 системных вызова","C":"Процесс ждёт в системном вызове epoll_wait — обычно следующего запроса клиента","D":"Процесс получил 232 сигнала"}'::jsonb, 'C', 'Вместо номера может стоять running (процесс выполняется) или -1 (ждёт не в системном вызове). Доступ зависит от владельца процесса и правил ptrace: к своим процессам он обычно есть, к чужим может понадобиться root; отказ в доступе не означает, что процесс не в системном вызове. Команды: cat /proc/PID/syscall; cat /proc/PID/wchan.', '{"A":"Номер в файле относится к системному вызову, а не к SQL-запросу.","B":"Файл показывает текущий вызов, а не счётчик.","C":"232 — номер epoll_wait на x86-64.","D":"Сигналы в этом файле не учитываются."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 30 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
